SELECT TABLE_NAME, COLUMN_NAME, DATA_TYPE, COLUMN_TYPE, IS_NULLABLE FROM information_schema.COLUMNS WHERE TABLE_SCHEMA='crypto_ai' AND (TABLE_NAME='candle' OR (TABLE_NAME IN ('paper_position','wallet_trade','trade_signal','market_price_event','production_exit_audit','wallet_managed_position','execution_opportunity') AND DATA_TYPE IN ('datetime','timestamp'))) ORDER BY TABLE_NAME, ORDINAL_POSITION;